function localDayKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function dayKeyFromDate(value,createdAt){if(typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value))return value;let d=value?new Date(value):null;if(!d||Number.isNaN(d.getTime()))d=createdAt?new Date(createdAt):new Date();return localDayKey(d)}
function thoughtDayLabel(key,opts={weekday:'long',month:'long',day:'numeric',year:'numeric'}){let [y,m,d]=key.split('-').map(Number);return new Date(y,m-1,d).toLocaleDateString(undefined,opts)}

function getNoteDisplayDate(n){
  const todayStr=new Date().toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'});
  if(!n)return todayStr;
  if(['highlights','snapshots','files','pdf'].includes(n.id)){
    const hasMedia=(n.attachments||[]).filter(isImageAttachment).length>0||(n.attachments&&n.attachments.length>0);
    if(!hasMedia)return todayStr;
    const ts=n.updatedAt||n.createdAt;
    if(ts)return new Date(ts).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'});
  }
  if(n.date&&!n.date.includes('25 May')&&!n.date.includes('1 Jun')&&!n.date.includes('Sep 29')){
    return n.date.split(',')[0];
  }
  if(n.createdAt){
    return new Date(n.createdAt).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'});
  }
  return todayStr;
}

const seedNotes=[
 {id:'files',kind:'files',title:'Files',body:'Your documents and saved files',attachments:[]},
 {id:'pdf',kind:'pdf',title:'Pdf',body:'Saved PDF documents',attachments:[]},
 {id:'audio',kind:'audio',title:'Audio',body:'Voice notes and audio clips',attachments:[]},
 {id:'highlights',kind:'image',title:'Highlights',body:'Your photo story',attachments:[]},
 {id:'snapshots',kind:'image',title:'Snapshots',body:'Moments worth keeping',attachments:[]}
];
let db=null, storageMode='indexeddb', memoryStore={}, notes=[],screen='home',filter='All Notes',query='',sort='edited',activeTab='Text',selectedId='thought',editorId=null,pendingFiles=[],removedFiles=[],recording=null,objectUrls=[],thoughtDraft=null,thoughtPending=[],thoughtRemoved=[],thoughtSlide='',thoughtDayKey=localDayKey(),thoughtEditReturn='home';
const app=document.getElementById('app'),overlay=document.getElementById('overlay');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();

function rawOpenDB(){return new Promise((resolve,reject)=>{if(!window.indexedDB){reject(new Error('IndexedDB not supported'));return}const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>req.result.createObjectStore(STORE,{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||new Error('IndexedDB open error'))})}
async function openDBWithRepair(){try{return await rawOpenDB()}catch(err){console.warn('[Storage] IndexedDB initial open failed, attempting database reset/repair:',err);try{if(window.indexedDB&&typeof indexedDB.deleteDatabase==='function'){await new Promise((resolve)=>{const deleteReq=indexedDB.deleteDatabase(DB_NAME);deleteReq.onsuccess=()=>resolve();deleteReq.onerror=()=>resolve();deleteReq.onblocked=()=>resolve()})}return await rawOpenDB()}catch(retryErr){console.warn('[Storage] IndexedDB repair retry failed:',retryErr);throw retryErr}}}
function request(req){return new Promise((resolve,reject)=>{req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}

async function allNotes(){if(storageMode==='indexeddb'&&db){try{return await request(db.transaction(STORE,'readonly').objectStore(STORE).getAll())}catch(e){console.warn('[Storage] IndexedDB read failed, switching to LocalStorage:',e);storageMode='localstorage'}}if(storageMode==='localstorage'){try{const raw=localStorage.getItem('your-notes-store');if(raw)return JSON.parse(raw)}catch(e){console.warn('[Storage] LocalStorage read failed, switching to Memory:',e);storageMode='memory'}}return Object.values(memoryStore)}
async function persist(n){if(storageMode==='indexeddb'&&db){try{return await request(db.transaction(STORE,'readwrite').objectStore(STORE).put(n))}catch(e){console.warn('[Storage] IndexedDB write failed, switching to LocalStorage:',e);storageMode='localstorage'}}if(storageMode==='localstorage'){try{let items=[];const raw=localStorage.getItem('your-notes-store');if(raw)items=JSON.parse(raw);const idx=items.findIndex(x=>x.id===n.id);if(idx>=0)items[idx]=n;else items.push(n);localStorage.setItem('your-notes-store',JSON.stringify(items));return}catch(e){console.warn('[Storage] LocalStorage write failed, switching to Memory:',e);storageMode='memory'}}memoryStore[n.id]=n}
async function removePersist(id){if(storageMode==='indexeddb'&&db){try{return await request(db.transaction(STORE,'readwrite').objectStore(STORE).delete(id))}catch(e){console.warn('[Storage] IndexedDB delete failed, switching to LocalStorage:',e);storageMode='localstorage'}}if(storageMode==='localstorage'){try{let items=[];const raw=localStorage.getItem('your-notes-store');if(raw)items=JSON.parse(raw);items=items.filter(x=>x.id!==id);localStorage.setItem('your-notes-store',JSON.stringify(items));return}catch(e){console.warn('[Storage] LocalStorage delete failed, switching to Memory:',e);storageMode='memory'}}delete memoryStore[id]}

async function init(){try{try{db=await openDBWithRepair();storageMode='indexeddb'}catch(idbErr){console.warn('[Storage] IndexedDB unavailable, using LocalStorage fallback mode:',idbErr);storageMode='localstorage'}notes=await allNotes();if(!notes.length){let old=[];try{old=JSON.parse(localStorage.getItem('your-notes-v1'))||[]}catch{};notes=old.length?old.map(normalize):structuredClone(seedNotes);for(const n of notes)await persist(n)}for(const n of [...notes]){if(n.date==='25 May 2026'||n.date==='Sep 29'||n.date==='1 Jun 2026')delete n.date;if(n.title==='Morning Reflection'&&(!n.quote||n.quote==='Embrace the moment and let your spirit soar.')){notes=notes.filter(x=>x.id!==n.id);removePersist(n.id);}}for(const seed of seedNotes){if(!notes.some(n=>n.id===seed.id)){notes.push(structuredClone(seed));persist(seed);}}let migrated=false;for(const n of notes.filter(x=>x.kind==='thought')){if(!n.dayKey){n.dayKey=dayKeyFromDate(n.date,n.createdAt);migrated=true}if(!n.createdAt){n.createdAt=Date.parse(n.date)||Date.now();migrated=true}if(n.date&&!Date.parse(n.date)){n.date=thoughtDayLabel(n.dayKey,{day:'numeric',month:'short',year:'numeric'});migrated=true}}if(migrated)await Promise.all(notes.filter(x=>x.kind==='thought').map(persist));thoughtDayKey=localDayKey();let todayThoughts=thoughtsForDay(thoughtDayKey);if(todayThoughts.length)selectedId=todayThoughts[0].id;render()}catch(e){console.error('[Storage] Fallback initialization due to error:',e);notes=structuredClone(seedNotes);thoughtDayKey=localDayKey();render()}}
function localDayKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function dayKeyFromDate(value,createdAt){if(typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value))return value;let d=value?new Date(value):null;if(!d||Number.isNaN(d.getTime()))d=createdAt?new Date(createdAt):new Date();return localDayKey(d)}
function thoughtDayLabel(key,opts={weekday:'long',month:'long',day:'numeric',year:'numeric'}){let [y,m,d]=key.split('-').map(Number);return new Date(y,m-1,d).toLocaleDateString(undefined,opts)}
function normalize(n){if(n.kind==='file')n.kind='files';if(Array.isArray(n.items)&&n.items.length&&Array.isArray(n.items[0]))n.items=n.items.map(([text,done])=>({text,done}));if(n.id==='shopping'&&n.title==='Shopping List'&&n.items?.length===3&&n.items[0].text==='Vegetables')n.items=n.items.map((x,i)=>({...x,done:i===0}));if(n.attachments?.length)n.attachments=n.attachments.filter(a=>a&&typeof a==='object'&&a.data);return n}
function save(){return Promise.all(notes.map(persist)).catch(()=>notify('Storage is full. Remove a large attachment and try again.'))}
function latest(kind){return notes.filter(n=>n.kind===kind&&!n.archived).sort((a,b)=>dateValue(b)-dateValue(a))[0]}
function dateValue(n){return n.updatedAt||n.createdAt||Date.parse(n.date)||0}
function visibleNotes(){let a=notes.filter(n=>!n.archived);if(filter==='To-Do')a=a.filter(n=>n.kind==='todo');if(filter==='Images')a=a.filter(n=>n.kind==='image');if(filter==='Important')a=a.filter(n=>n.favorite||n.pinned);if(query)a=a.filter(n=>`${n.title} ${n.body||''} ${n.quote||''}`.toLowerCase().includes(query.toLowerCase()));if(sort==='alpha')a.sort((x,y)=>x.title.localeCompare(y.title));else if(sort==='oldest')a.sort((x,y)=>dateValue(x)-dateValue(y));else a.sort((x,y)=>Number(!!y.pinned)-Number(!!x.pinned)||dateValue(y)-dateValue(x));return a}
function triggerFileInput(id){const el=document.getElementById(id);if(el){el.value='';el.click();return true}return false}
function cleanupUrls(){objectUrls.forEach(URL.revokeObjectURL);objectUrls=[]}
function dataUrlToBlob(dataUrl){if(typeof dataUrl!=='string'||!dataUrl.startsWith('data:'))return null;try{const parts=dataUrl.split(',');const mimeMatch=parts[0].match(/:(.*?);/);const mime=mimeMatch?mimeMatch[1]:'image/jpeg';const bstr=atob(parts[1]);let n=bstr.length;const u8arr=new Uint8Array(n);while(n--){u8arr[n]=bstr.charCodeAt(n)}return new Blob([u8arr],{type:mime})}catch(_){return null}}
function fileUrl(file){if(!file)return null;let raw=file.data||file;while(raw&&typeof raw==='object'&&!(raw instanceof Blob)&&!(raw instanceof File)&&raw.data){raw=raw.data}if(typeof raw==='string'){if(raw.startsWith('data:')){const blob=dataUrlToBlob(raw);if(blob){try{const u=URL.createObjectURL(blob);objectUrls.push(u);return u}catch(_){}}}return raw}if(raw&&(raw instanceof Blob||raw instanceof File)){try{const u=URL.createObjectURL(raw);objectUrls.push(u);return u}catch(_){return null}}return null}
function isImageAttachment(x){if(!x)return false;let raw=x.data||x;while(raw&&typeof raw==='object'&&!(raw instanceof Blob)&&!(raw instanceof File)&&raw.data){raw=raw.data}const t=x.type||mimeFromName(x.name||'');return(t.startsWith('image/')||(typeof raw==='string'&&raw.startsWith('data:image/')))&&(!!raw)}
function fileToDataUrl(file){return new Promise((resolve)=>{if(!file){resolve(null);return}if(typeof file==='string'){resolve(file);return}if(file.data&&typeof file.data==='string'){resolve(file.data);return}const blob=file.data||file;const reader=new FileReader();reader.onload=function(e){resolve(e.target?.result||null)};reader.onerror=function(){resolve(null)};try{reader.readAsDataURL(blob)}catch(_){resolve(null)}})}
async function processFileObject(file){if(!file)return null;console.log('[FilePipeline] Processing non-image file:', file.name, file.type, file.size);const dataUrl=await fileToDataUrl(file);if(!dataUrl){return{id:uid(),name:file.name||'document',type:file.type||mimeFromName(file.name||''),data:file}}return{id:uid(),name:file.name||'document',type:file.type||mimeFromName(file.name||''),data:dataUrl}}
async function processImageFile(file){if(!file)return null;console.log('[FilePipeline] processImageFile start:', file.name, file.type, file.size);let dataUrl=await fileToDataUrl(file);if(!dataUrl){console.warn('[FilePipeline] fileToDataUrl failed for image:', file.name);return{id:uid(),name:file.name||'photo.jpg',type:file.type||'image/jpeg',data:file}}try{const processedDataUrl=await new Promise((resolve)=>{const img=new Image();const objectUrl=URL.createObjectURL(file);img.onload=()=>{URL.revokeObjectURL(objectUrl);const maxDim=2000;let width=img.width,height=img.height;if(width>maxDim||height>maxDim){if(width>height){height=Math.round((height*maxDim)/width);width=maxDim}else{width=Math.round((width*maxDim)/height);height=maxDim}}const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d');if(!ctx){resolve(dataUrl);return}try{ctx.drawImage(img,0,0,width,height);const compressed=canvas.toDataURL('image/jpeg',0.85);console.log('[FilePipeline] Image canvas compression succeeded:', file.name);resolve(compressed)}catch(canvasErr){console.warn('[FilePipeline] Canvas drawImage/toDataURL failed, using original:', canvasErr);resolve(dataUrl)}};img.onerror=(err)=>{URL.revokeObjectURL(objectUrl);console.warn('[FilePipeline] Image decode failed (unsupported format/corrupt?), using original file dataUrl:', file.name, err);resolve(dataUrl)};img.src=objectUrl});return{id:uid(),name:file.name||'photo.jpg',type:file.type||mimeFromName(file.name||'')||'image/jpeg',data:processedDataUrl}}catch(err){console.warn('[FilePipeline] processImageFile exception, falling back to original:', err);return{id:uid(),name:file.name||'photo.jpg',type:file.type||mimeFromName(file.name||'')||'image/jpeg',data:dataUrl}}}
async function processMultipleFiles(files){console.log('[FilePipeline] processMultipleFiles called with count:', files?.length);const processed=[];for(const f of files){const type=f.type||mimeFromName(f.name||'');console.log('[FilePipeline] Inspecting file:', f.name, type, f.size);let item=null;if(type.startsWith('image/')||(f.name&&/\.(jpe?g|png|webp|gif|bmp)$/i.test(f.name))){item=await processImageFile(f)}else{item=await processFileObject(f)}if(item&&(item.data||item.file)){processed.push(item)}else{console.warn('[FilePipeline] File processing returned null, using fallback for:', f.name);processed.push({id:uid(),name:f.name||'file',type:type||'application/octet-stream',data:f})}}console.log('[FilePipeline] processMultipleFiles finished. Processed count:', processed.length);return processed}
function cleanPhotoTitle(f){if(f.title)return f.title;if(!f.name)return '';if(/^(img|dsc|photo|picture|screenshot|capture)[_-]?\d+/i.test(f.name)||/^\d{8,}/.test(f.name)||/\.(jpe?g|png|webp|gif|heic|heif)$/i.test(f.name)&&f.name.length<15){return ''}return f.name.replace(/\.[^.]+$/, '').replace(/[_-_]/g, ' ')}
function openPhotoViewer(note,photo){const url=fileUrl(photo);modalShell(`<div class="photo-viewer-modal" style="text-align:center"><div class="viewer-head" style="display:flex;justify-content:flex-end;margin-bottom:8px"><button class="circle viewer-close" aria-label="Close" style="width:40px;height:40px">×</button></div><div class="viewer-img-container" style="margin:8px 0 16px"><img src="${url}" alt="${esc(photo.title||photo.name||'Photo')}" style="max-width:100%;max-height:68vh;object-fit:contain;border-radius:20px;box-shadow:0 12px 30px #0004"></div><div class="modal-actions" style="justify-content:center"><button class="action danger" data-delete-photo style="background:#e85d6da8;color:white;border-radius:24px;padding:12px 24px">Delete Photo</button></div></div>`);overlay.querySelector('.viewer-close').onclick=closeModal;overlay.querySelector('.modal-back').onclick=e=>{if(e.target.classList.contains('modal-back'))closeModal()};overlay.querySelector('[data-delete-photo]').onclick=async()=>{if(!confirm('Delete this photo permanently?'))return;note.attachments=(note.attachments||[]).filter(x=>x.id!==photo.id);note.updatedAt=Date.now();await persist(note);closeModal();render();notify('Photo deleted.')}}
async function openFileViewer(file){
  console.log('[PdfBridge] Opening file:', file.name, file.type);
  const isPdf = file.type === 'application/pdf' || (file.name && file.name.toLowerCase().endsWith('.pdf'));

  if (isPdf && window.AndroidPdf && typeof window.AndroidPdf.openPdfBase64 === 'function') {
    try {
      notify('Opening PDF…');
      let dataUrl = await fileToDataUrl(file);
      if (dataUrl) {
        window.AndroidPdf.openPdfBase64(dataUrl, file.name || 'document.pdf');
        return;
      }
    } catch (e) {
      console.warn('[PdfBridge] AndroidPdf bridge failed, falling back to viewer modal:', e);
    }
  }

  const url=fileUrl(file);
  modalShell(`
    <div class="file-viewer-modal" style="display:flex;flex-direction:column;max-height:85vh">
      <div class="viewer-head" style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px">
        <h2 style="margin:0;font-size:18px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:80%">${esc(file.name)}</h2>
        <button class="circle viewer-close" aria-label="Close" style="width:40px;height:40px">×</button>
      </div>
      <div class="file-viewer-content" style="flex:1;overflow:auto;margin:4px 0 12px">
        <p style="margin:4px 0;font-size:13px;color:#556b82"><strong>Type:</strong> ${esc(file.type||'Document')} · <strong>Size:</strong> ${formatBytes(file.data?.size||0)}</p>
        ${file.type==='application/pdf'||file.type?.startsWith('image/')||file.type?.startsWith('text/')?`<iframe class="file-preview-iframe" src="${url}" title="${esc(file.name)}" style="width:100%;height:380px;border:1px solid #d5e3ef;border-radius:14px;background:#fff;margin-top:10px"></iframe>`:`<p style="text-align:center;padding:30px;color:#667c8e">Preview not available for this file format.</p>`}
      </div>
      <div class="modal-actions" style="justify-content:space-between">
        <a class="action primary" href="${url}" download="${esc(file.name)}" target="_blank" style="background:#3e789f;color:white;border-radius:22px;padding:12px 20px;text-decoration:none">Download / Open</a>
        <button class="action" data-close style="border-radius:22px;padding:12px 20px">Close</button>
      </div>
    </div>
  `);
  overlay.querySelector('.viewer-close').onclick=closeModal;
  overlay.querySelector('[data-close]').onclick=closeModal;
  overlay.querySelector('.modal-back').onclick=e=>{if(e.target.classList.contains('modal-back'))closeModal()};
}
function render(){cleanupUrls();app.innerHTML=screen==='home'?homeView():screen==='thoughts'?thoughtView():screen==='thoughtHistory'?thoughtHistoryView():screen==='thoughtEdit'?thoughtEditorView():screen==='morning'?morningView():screen==='album'?albumView():screen==='audio'?audioView():detailView();bindGlobal();if(screen==='album')bindAlbum();if(screen==='audio')bindAudioLibrary();if(screen==='thoughts')bindThoughtAudio();}
function homeView(){const chips=['All Notes','To-Do','Images','Important'],list=dashboardItems(visibleNotes());return `<section class="screen home-screen"><header class="topline"><div class="logo" aria-label="Your Notes">${logoSvg()}</div><button class="circle" data-action="menu" aria-label="More options"><span class="dots">∷</span></button></header><h1 class="title">Your Notes</h1><nav class="filters">${chips.map(c=>`<button class="chip ${filter===c?'active':''}" data-filter="${c}">${c}</button>`).join('')}</nav><div class="grid">${list.map(card).join('')||'<div class="empty">No notes here yet. Tap + to create one.</div>'}</div><div class="fabbar"><button class="fab" data-action="create" aria-label="Create note">${plusSvg()}</button><button class="fab mic ${recording?'recording':''}" data-action="record" aria-label="Record voice note">${micSvg()}</button></div></section>`}
function dashboardItems(list){let seenAudio=false;let filtered=list.filter(n=>{if(n.kind==='audio'){if(!seenAudio){seenAudio=true;return true}return false}return true});const all=filtered.filter(n=>n.kind==='thought');if(!all.length){const defaultThought={id:'thought',kind:'thought',title:'',quote:'',body:'',dayKey:localDayKey(),createdAt:Date.now()};filtered.unshift(defaultThought)}else{const first=filtered.findIndex(n=>n.kind==='thought'),insertAt=filtered.slice(0,first).filter(n=>n.kind!=='thought').length,featured=[...all].sort((a,b)=>(b.dayKey||dayKeyFromDate(a.date,a.createdAt)).localeCompare(a.dayKey||dayKeyFromDate(b.date,b.createdAt))||(b.createdAt||0)-(a.createdAt||0))[0],others=filtered.filter(n=>n.kind!=='thought');others.splice(Math.min(insertAt,others.length),0,featured);filtered=others}return filtered}
function card(n){const title=esc(n.title);if(n.kind==='todo')return `<article class="tile shopping" data-open="${n.id}"><h2>${n.title==='Shopping List'?'Shopping<br>List':title}</h2>${(n.items||[]).slice(0,3).map((x,i)=>`<button class="checkrow ${x.done?'checked':''}" data-check="${n.id}" data-index="${i}"><span class="check ${x.done?'on':''}">${x.done?'✓':''}</span>${esc(x.text)}</button>`).join('')}</article>`;if(n.kind==='thought')return `<article class="tile thought-tile" data-open="${n.id}"><strong>Thought<br>of the<br>day</strong><span class="date">${esc(getNoteDisplayDate(n))}</span></article>`;if(n.kind==='audio')return `<article class="tile audio" data-open="${n.id}"><span class="play">▶</span><div class="wave">${[13,26,34,24,40,29,17,35,24,43,23,32,18].map((h,i)=>`<i style="--h:${h}px;--d:${i*.07}s"></i>`).join('')}</div></article>`;if(n.kind==='files')return `<article class="tile files" data-open="${n.id}"><div class="docs"><span></span><span></span></div>Files</article>`;if(n.kind==='pdf')return `<article class="tile pdf" data-open="${n.id}"><div class="docs"><span></span><span></span></div>Pdf</article>`;if(n.id==='highlights'||n.id==='snapshots'||n.kind==='image'){let photos=(n.attachments||[]).filter(isImageAttachment),cover=photos[photos.length-1]||photos[0],url=cover&&fileUrl(cover),count=photos.length,dateText=getNoteDisplayDate(n);if(url){return `<article class="tile photo user-image has-photo" data-open="${n.id}" style="background-image:linear-gradient(180deg,#15253622,#152536aa),url('${url}')"><div><strong>${title}</strong><small>${esc(dateText)}</small></div><div style="display:flex;gap:6px;align-self:flex-end"><span class="badge">+${count}</span><span class="badge">Photos</span></div></article>`}}let img=n.attachments?.find(isImageAttachment),url=img&&fileUrl(img),count=(n.attachments||[]).filter(isImageAttachment).length,coverClass=n.id==='highlights'?'photo-scene':n.id==='snapshots'?'snapshot-scene':'',dateText=getNoteDisplayDate(n);return `<article class="tile photo ${n.kind==='image'?'user-image':''} ${coverClass} ${url?'has-photo':''}" data-open="${n.id}" ${url?`style="background-image:linear-gradient(180deg,#15253612,#15253688),url('${url}')"`:''}><div><strong>${title}</strong><small>${esc(dateText)}</small></div><span class="badge">${count?`▧ ${count} ${count===1?'Photo':'Photos'}`:'＋ Add photos'}</span></article>`}
function thoughtView(){const thoughtList=thoughtsForDay(thoughtDayKey),n=thoughtList.find(x=>x.id===selectedId)||thoughtList[0],days=thoughtDayKeys(),dayIndex=days.indexOf(thoughtDayKey),label=thoughtDayKey===localDayKey()?'Today':thoughtDayLabel(thoughtDayKey,{weekday:'short',month:'short',day:'numeric'});if(!n)return `<section class="screen detail thought-detail"><div class="detail-head"><button class="circle back" data-action="back">${backSvg()}</button><button class="circle" data-action="thought-history" aria-label="Thought history">↗</button></div><h1 class="detail-title">Thought of<br>the day</h1><div class="thought-daybar"><button data-action="day-prev" aria-label="Previous day" ${dayIndex<=0?'disabled':''}>‹</button><span><strong>${esc(label)}</strong><small>${esc(thoughtDayLabel(thoughtDayKey))}</small></span><button data-action="day-next" aria-label="Next day" ${dayIndex<0||dayIndex>=days.length-1?'disabled':''}>›</button><button class="history-link" data-action="thought-history">History <b>↗</b></button></div><div class="note empty-thought"><p>No thoughts saved for this day.</p><p>Capture a thought and it will stay in this date’s journal.</p></div><button class="create-new" data-action="new-thought"><b>+</b> Add a thought</button></section>`;let imgs=n.attachments?.filter(isImageAttachment)||[],audios=n.attachments?.filter(x=>x.type?.startsWith('audio/')&&x.data)||[];let content=activeTab==='Text'?`<h2>${esc(n.quote||n.title)}</h2><p>${esc(n.body||'')}</p>${imgs.length?`<div class="attachments thought-attachments">${imgs.slice(0,2).map(imageMarkup).join('')}</div>`:''}`:activeTab==='Images'?imgs.length?`<div class="attachment-gallery">${imgs.map(imageMarkup).join('')}</div>`:`<div class="attachment-empty">No images on this thought yet. Tap the pencil to add one.</div>`:audios.length?`<div class="thought-audio-list">${audios.map(audioMarkup).join('')}</div>`:`<div class="attachment-empty thought-audio-empty"><span class="audio-empty-mark">♫</span><strong>A little space for your voice</strong><p>Add a recording or audio clip to this thought.</p><button data-action="thought-audio">＋ Add audio</button></div>`;
const index=thoughtList.findIndex(x=>x.id===n.id),behind=[thoughtList[(index+1)%thoughtList.length],thoughtList[(index+2)%thoughtList.length]].filter((x,i)=>thoughtList.length>1&&x&&x.id!==n.id&&(!i||x.id!==thoughtList[(index+1)%thoughtList.length]?.id));while(behind.length<2)behind.push(null);const slide=thoughtSlide;thoughtSlide='';return `<section class="screen detail thought-detail ${slide}"><div class="detail-head"><button class="circle back" data-action="back">${backSvg()}</button><button class="circle" data-action="menu" aria-label="Thought options"><span class="dots">•••</span></button></div><h1 class="detail-title">Thought of<br>the day</h1><div class="thought-daybar"><button data-action="day-prev" aria-label="Previous day" ${dayIndex<=0?'disabled':''}>‹</button><span><strong>${esc(label)}</strong><small>${esc(thoughtDayLabel(thoughtDayKey))}</small></span><button data-action="day-next" aria-label="Next day" ${dayIndex<0||dayIndex>=days.length-1?'disabled':''}>›</button><button class="history-link" data-action="thought-history">History <b>↗</b></button></div><div class="tabs">${['Text','Images','Audios'].map(t=>`<button class="tab ${activeTab===t?'active':''}" data-tab="${t}">${t}</button>`).join('')}</div><div class="thought-deck" data-thought-deck tabindex="0" aria-label="Thought cards. Swipe left or right to move between thoughts">${behind.map((x,i)=>`<div class="thought-backcard backcard-${i+1}" aria-hidden="true">${i===0?`<small>${esc(x?.title||'Another thought')}</small>`:''}</div>`).join('')}<article class="note thought-current"><div class="note-meta"><strong>${esc(n.title||'Morning Reflection')}</strong>${esc(thoughtDayLabel(n.dayKey||thoughtDayKey,{day:'numeric',month:'short',year:'numeric'}))}${n.updatedAt&&n.createdAt&&n.updatedAt>n.createdAt?'<small class="thought-edited">Edited</small>':''}</div><button class="edit" data-action="edit" aria-label="Edit thought">${editSvg()}</button>${content}</article></div>${thoughtNav(n)}<button class="create-new" data-action="new-thought"><b>+</b> Add a thought</button><input id="thought-view-audio" class="hidden-media-input" type="file" accept="audio/*" multiple></section>`}
function thoughtHistoryView(){let all=thoughtsCollection(),groups=new Map();for(const n of all){const key=n.dayKey||dayKeyFromDate(n.date,n.createdAt);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(n)}const days=[...groups.keys()].sort((a,b)=>b.localeCompare(a));return `<section class="screen thought-history"><div class="history-top"><button class="circle back" data-action="back">${backSvg()}</button><span>YOUR JOURNAL</span><button class="circle" data-action="thought-today" aria-label="Go to today">⌖</button></div><header class="history-heading"><p>THOUGHTS, KEPT OVER TIME</p><h1>Your<br>History</h1><span>${all.length} ${all.length===1?'thought':'thoughts'} · ${days.length} ${days.length===1?'day':'days'}</span></header>${days.length?`<div class="history-list">${days.map((day,i)=>`<section class="history-day"><div class="history-date"><span class="history-date-mark">${String(Number(day.slice(8)))}</span><div><strong>${esc(day===localDayKey()?'Today':thoughtDayLabel(day,{weekday:'long',month:'long',day:'numeric'}))}</strong><small>${esc(thoughtDayLabel(day,{month:'long',year:'numeric'}))} · ${groups.get(day).length} ${groups.get(day).length===1?'thought':'thoughts'}</small></div><span class="history-index">${String(i+1).padStart(2,'0')}</span></div><div class="history-cards">${groups.get(day).map(n=>{const imageCount=(n.attachments||[]).filter(f=>f.type?.startsWith('image/')).length,audioCount=(n.attachments||[]).filter(f=>f.type?.startsWith('audio/')).length;return `<button class="history-card" data-history-note="${n.id}"><span class="history-card-time">${esc(new Date(n.createdAt||Date.now()).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}))}</span><strong>${esc(n.quote||n.title||'Untitled thought')}</strong><small>${esc(n.body||'Open to revisit this moment.')}</small><span class="history-card-meta">${imageCount?`▧ ${imageCount}`:''}${audioCount?`♫ ${audioCount}`:''}<b>Open thought　↗</b></span></button>`}).join('')}</div></section>`).join('')}</div>`:`<div class="history-empty"><span>✳</span><h2>Your story starts here</h2><p>Thoughts you save will be gathered here by date, so every day stays easy to find.</p><button class="create-new" data-action="new-thought"><b>+</b> Write your first thought</button></div>`}<div class="history-bottom"><button class="create-new" data-action="new-thought"><b>+</b> Write a thought</button></div></section>`}
function thoughtEditorView(){let d=thoughtDraft||{},files=[...(d.attachments||[]).filter(f=>!thoughtRemoved.includes(f.id)),...thoughtPending];return `<section class="screen thought-write"><div class="write-head"><button class="circle back" data-action="back">${backSvg()}</button><div class="write-actions"><button class="circle" data-action="thought-options" aria-label="More thought actions"><span class="dots">•••</span></button><button class="write-save" data-action="save-thought"><span aria-hidden="true">✓</span> Save</button></div></div><div class="write-content"><div class="write-date">${esc(d.date||'TODAY’S THOUGHT')}</div><input id="thought-title" class="write-quote" style="font-size:24px;min-height:auto;margin-bottom:12px;font-weight:600;color:#121d2a;display:block;width:100%;border:0;outline:0;background:transparent;font:inherit" value="${esc(d.title||'')}" placeholder="Title"><textarea id="thought-quote" class="write-quote" rows="3" placeholder="What would you like to remember?">${esc(d.quote||'')}</textarea><textarea id="thought-body" class="write-body" rows="5" placeholder="Tap here to continue…">${esc(d.body||'')}</textarea>${files.length?`<div class="write-attachments">${files.map(f=>f.type?.startsWith('image/')?`<div class="write-thumb"><img src="${fileUrl(f)}" alt="${esc(f.name)}"><button data-remove-thought-file="${esc(f.id||f.name)}" aria-label="Remove ${esc(f.name)}">×</button></div>`:f.type?.startsWith('audio/')?`<div class="write-audio">♫ ${esc(f.name)}</div>`:'').join('')}</div>`:''}</div><div class="thought-toolbar" role="toolbar" aria-label="Thought tools"><button data-action="thought-ideas" aria-label="Writing ideas" title="Writing ideas">✦</button><button data-action="thought-camera" aria-label="Take photo" title="Take a photo">${cameraSvg()}</button><button data-action="thought-images" aria-label="Choose images" title="Choose images">${imageSvg()}</button><button data-action="focus-thought" aria-label="Continue writing" title="Continue writing">${editSvg()}</button></div><input id="thought-camera-input" class="hidden-media-input" type="file" accept="image/*" capture="environment"><input id="thought-image-input" class="hidden-media-input" type="file" accept="image/*" multiple><input id="thought-audio-input" class="hidden-media-input" type="file" accept="audio/*" multiple></section>`}
function morningView(){let t=notes.find(n=>n.id===selectedId&&n.kind==='thought')||latest('thought'),highlight=latest('image'),now=new Date(),weekday=now.toLocaleDateString(undefined,{weekday:'long'}),monthDay=now.toLocaleDateString(undefined,{month:'short',day:'numeric'});return `<section class="screen morning-screen"><div class="morning-top"><button class="circle back" data-action="back">${backSvg()}</button><button class="circle" data-action="menu" aria-label="More options"><span class="dots">∷</span></button></div><p class="morning-eyebrow">A LITTLE SPACE FOR YOU</p><h1>Good<br>Morning<span class="morning-spark">✳</span></h1><div class="morning-board">${t?`<button class="morning-thought" data-open="${t.id}"><small>Thought of the day</small><strong>${esc(t.quote||t.title)}</strong><span>${esc(t.date||'')}</span></button>`:''}${highlight?`<article class="morning-highlight">${card(highlight)}<span>Highlights</span></article>`:''}<button class="morning-date" data-action="daily-notes"><strong>${weekday}</strong><span>${monthDay}</span><small>Daily overview · ${notes.filter(n=>!n.archived).length} notes</small></button></div><div class="morning-footer"><button class="morning-continue" data-action="morning-thought">Open today’s thought　↗</button></div></section>`}
function albumView(){const n=notes.find(x=>x.id===selectedId&&['highlights','snapshots'].includes(x.id));if(!n)return homeView();const photos=(n.attachments||[]).filter(isImageAttachment),isSnapshots=n.id==='snapshots',label=isSnapshots?'Snapshots':'Highlights',todayStr=new Date().toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'}),date=(n.date&&n.date!=='25 May 2026'&&n.date!=='Sep 29')?n.date.split(',')[0]:todayStr,cover=photos[0],coverUrl=cover&&fileUrl(cover);const coverTitle=cover?(cover.title||cleanPhotoTitle(cover)||label):label;return `<section class="screen album-screen ${isSnapshots?'snapshots-screen':''}"><div class="album-top"><button class="circle back" data-action="back" aria-label="Back">${backSvg()}</button><button class="circle" data-action="menu" aria-label="More options"><span class="dots">•••</span></button></div><header class="album-heading"><span class="album-kicker">${isSnapshots?'LITTLE MOMENTS, KEPT':'YOUR PHOTO STORY'}</span><h1>${label}</h1><p>${photos.length} ${photos.length===1?'photo':'photos'} <span>·</span> ${esc(date)}</p></header>${photos.length?`<button class="album-cover" data-album-image="0"><img class="album-cover-bg" src="${coverUrl||''}" alt="${esc(cover.name||label)}"><span class="cover-tag">${isSnapshots?'A moment to keep':'In your highlights'}</span><strong>${esc(coverTitle)}</strong><small>${photos.length>1?`+${photos.length-1} more in this album`:'Tap to view photo'}</small></button>${photos.length>1?`<div class="album-grid">${photos.slice(1).map((f,i)=>{const t=f.title||cleanPhotoTitle(f);return `<button class="album-photo" data-album-image="${i+1}" aria-label="View ${esc(f.name||'photo')}"><img src="${fileUrl(f)}" alt="${esc(f.name||'Photo')}">${t?`<span>${esc(t)}</span>`:''}</button>`}).join('')}</div>`:''}`:`<div class="album-empty"><div class="empty-art ${isSnapshots?'warm':''}"><span>✳</span><i></i><b></b></div><h2>${isSnapshots?'Save the little moments':'Your highlights begin here'}</h2><p>Add photos you want to find again. They’ll become this album’s cover and gallery.</p><button class="empty-add" data-action="album-add">＋ Add photos</button></div>`}${photos.length?`<button class="album-add-fab" data-action="album-add"><span>＋</span><b>Add photos</b></button>`:''}<input id="album-files" class="hidden-media-input" type="file" accept="image/*" multiple></section>`}
function bindAlbum(){const input=document.getElementById('album-files');if(input)input.onchange=async()=>{const files=Array.from(input.files||[]);input.value='';if(files.length)await addAlbumPhotos(files)};document.querySelectorAll('[data-album-image]').forEach(x=>x.onclick=()=>showAlbumPhoto(+x.dataset.albumImage));}
async function addAlbumPhotos(files){const n=notes.find(x=>x.id===selectedId);if(!n)return;const previous=structuredClone(n);notify('Adding photo…');try{const processed=await processMultipleFiles(files);n.attachments=[...(n.attachments||[]),...processed];n.date=new Date().toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'});n.updatedAt=Date.now();await persist(n);notify(`${files.length} ${files.length===1?'photo':'photos'} added to ${n.title}.`);render()}catch{Object.assign(n,previous);notify('Could not save photo. Try selecting a smaller image.');render()}}
function showAlbumPhoto(index){const n=notes.find(x=>x.id===selectedId),photos=(n?.attachments||[]).filter(isImageAttachment),f=photos[index];if(!f)return;openPhotoViewer(n,f)}
function audioCardPlayerMarkup(note,file){let u=fileUrl(file),bars=[13,22,17,30,20,35,15,27,39,21,32,16,25,36,19,29,14];let bodyHtml=note.body&&note.body!=='Added from your device.'?`<p class="audio-card-desc">${esc(note.body)}</p>`:'';return `<div class="audio-card-content">${bodyHtml}<div class="audio-mini-wave" aria-hidden="true">${bars.map((h,i)=>`<i style="--h:${h}px;--d:${i*.05}s"></i>`).join('')}</div><audio controls preload="metadata" src="${u||''}"></audio></div>`}
function audioEntries(){return notes.filter(n=>n.kind==='audio'&&!n.archived).flatMap(note=>(note.attachments||[]).filter(f=>f.type?.startsWith('audio/')&&f.data).map(file=>({note,file}))).sort((a,b)=>dateValue(b.note)-dateValue(a.note))}
function audioView(){const entries=audioEntries(),isRecording=recording?.state==='recording';return `<section class="screen audio-screen"><div class="audio-top"><button class="circle back" data-action="back" aria-label="Back">${backSvg()}</button><button class="circle" data-action="menu" aria-label="More options"><span class="dots">•••</span></button></div><header class="audio-heading"><span class="audio-kicker">SOUND, KEPT</span><h1>Your<br>Audio</h1><p>Little moments, just as you heard them.</p></header><div class="audio-actions"><button class="audio-record ${isRecording?'recording':''}" data-action="record">${isRecording?'<span class="stop-mark">■</span>':'<span class="audio-mic">'+micSvg()+'</span>'}<span>${isRecording?'Finish recording':'Record a thought'}</span></button><button class="audio-upload" data-action="audio-add">＋ Add audio</button></div>${isRecording?'<div class="recording-status"><i></i> Recording in progress <span>Tap “Finish recording” when you’re done.</span></div>':''}<div class="audio-library-head"><div><span>YOUR LIBRARY</span><h2>Recent recordings</h2></div><b>${entries.length}</b></div>${entries.length?`<div class="audio-library">${entries.map(({note,file})=>`<article class="audio-record-card"><div class="audio-record-meta"><span class="audio-record-icon">♫</span><div><strong>${esc(note.title||file.name||'Voice note')}</strong><small>${esc(note.date||'')} · ${formatBytes(file.data?.size||0)}</small></div><button class="audio-edit" data-edit-audio="${note.id}" aria-label="Edit audio details">•••</button></div>${audioCardPlayerMarkup(note,file)}</article>`).join('')}</div>`:`<div class="audio-empty"><div class="audio-orb"><span>♫</span></div><h2>Your recordings will live here</h2><p>Record a voice note or add an audio file to start your collection.</p></div>`}<input id="audio-library-files" class="hidden-media-input" type="file" accept="audio/*" multiple></section>`}
function bindAudioLibrary(){const input=document.getElementById('audio-library-files');if(input)input.onchange=()=>{const files=Array.from(input.files||[]);input.value='';if(files.length)openAudioEditor(null,files)};document.querySelectorAll('[data-edit-audio]').forEach(b=>b.onclick=()=>{const note=notes.find(n=>n.id===b.dataset.editAudio);if(note)openAudioEditor(note)})}
function openAudioEditor(n,files){editorId=n?.id||null;let draftFiles=files||(n?.attachments?[...n.attachments]:[]);let isNew=!n;let defaultTitle=draftFiles[0]?.name?draftFiles[0].name.replace(/\.[^.]+$/,''):'Audio note';let title=n?.title||defaultTitle;let body=n?.body&&n.body!=='Added from your device.'?n.body:'';let primaryFile=draftFiles.find(f=>f.type?.startsWith('audio/'))||draftFiles[0];let filePreviewUrl=primaryFile?fileUrl(primaryFile):null;let fileSizeText=primaryFile?.data?.size?formatBytes(primaryFile.data.size):primaryFile?.size?formatBytes(primaryFile.size):'';modalShell(`<div class="audio-editor-modal"><h2>${isNew?'Add Audio Details':'Audio Details'}</h2>${primaryFile?`<div class="audio-editor-preview"><div class="audio-clip-head"><span class="audio-clip-icon">♫</span><div><strong>${esc(primaryFile.name||'Audio file')}</strong><small>${esc(primaryFile.type?.split('/')[1]?.toUpperCase()||'AUDIO')}${fileSizeText?' · '+fileSizeText:''}</small></div></div><audio controls preload="metadata" src="${filePreviewUrl||''}"></audio></div>`:''}<label>Title<input class="field" id="audio-title" value="${esc(title)}" placeholder="Audio Title"></label><label>Description / Notes<textarea class="field" id="audio-body" rows="3" placeholder="Add details or notes...">${esc(body)}</textarea></label>${n?`<div class="menu-items note-actions"><button data-note-action="favorite">${n.favorite?'★ Remove favorite':'☆ Favorite'}</button><button data-note-action="pin">${n.pinned?'Unpin':'Pin'}</button><button data-note-action="share">Share</button></div>`:''}<div class="modal-actions">${n?'<button class="action danger" data-delete-audio>Delete</button>':''}<button class="action" data-close>Cancel</button><button class="action primary" data-save-audio>Save</button></div></div>`);overlay.querySelector('[data-close]').onclick=closeModal;overlay.querySelector('[data-save-audio]').onclick=()=>saveAudioEditor(n,draftFiles);if(n){overlay.querySelector('[data-delete-audio]')?.addEventListener('click',()=>deleteAudioNote(n.id));overlay.querySelectorAll('[data-note-action]').forEach(b=>b.onclick=()=>noteAction(b.dataset.noteAction))}}
async function saveAudioEditor(existingNote,files){let title=overlay.querySelector('#audio-title')?.value.trim()||'Audio note',body=overlay.querySelector('#audio-body')?.value.trim()||'',previous=existingNote?structuredClone(existingNote):null;let attachments=(files||[]).map(f=>({id:f.id||uid(),name:f.name,type:f.type||mimeFromName(f.name),data:f.data||f}));let note=existingNote||{id:uid(),kind:'audio',date:new Date().toLocaleString(),createdAt:Date.now()};note.title=title;note.body=body;note.updatedAt=Date.now();note.attachments=attachments.length?attachments:(existingNote?.attachments||[]);if(!existingNote)notes.unshift(note);try{await persist(note);selectedId=note.id;screen='audio';closeModal();render();notify(existingNote?'Audio details saved.':'Audio saved to library.')}catch(err){if(existingNote)Object.assign(existingNote,previous);else notes=notes.filter(x=>x.id!==note.id);notify('Could not save audio. Check device storage.')}}
async function deleteAudioNote(id){if(!confirm('Delete this audio permanently?'))return;notes=notes.filter(x=>x.id!==id);await removePersist(id);closeModal();render();notify('Audio deleted.')}
function bindThoughtAudio(){const input=document.getElementById('thought-view-audio');if(input)input.onchange=()=>{const files=Array.from(input.files||[]);input.value='';if(files.length)addThoughtAudio(files)}}
async function addThoughtAudio(files){const note=notes.find(n=>n.id===selectedId&&n.kind==='thought');if(!note)return;const previous=structuredClone(note);note.attachments=[...(note.attachments||[]),...files.map(f=>({id:uid(),name:f.name,type:f.type||mimeFromName(f.name),data:f}))];note.updatedAt=Date.now();try{await persist(note);notify(`${files.length} audio ${files.length===1?'clip':'clips'} added to this thought.`);render()}catch{Object.assign(note,previous);notify('Could not save this audio. Check available device storage.')}}
function cameraSvg(){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 8h3l1.5-2h7L17 8h3v11H4z"/><circle cx="12" cy="13" r="3.2"/></svg>'}function imageSvg(){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="4" width="18" height="16" rx="2.5"/><circle cx="8.5" cy="9" r="1.5"/><path d="m4 17 5-5 3 3 3-4 5 6"/></svg>'}
function beginThoughtEdit(n){thoughtEditReturn=screen;editorId=n?.id||null;thoughtDraft=n?structuredClone(n):{id:uid(),kind:'thought',title:'',quote:'',body:'',date:new Date().toLocaleString(),dayKey:localDayKey(),attachments:[],createdAt:Date.now()};thoughtPending=[];thoughtRemoved=[];screen='thoughtEdit';render()}
async function saveThoughtEdit(){if(!thoughtDraft)return;const prev=editorId?notes.find(n=>n.id===editorId):null;thoughtDraft.title=document.getElementById('thought-title')?.value?.trim()||'';thoughtDraft.quote=document.getElementById('thought-quote')?.value.trim()||'';thoughtDraft.body=document.getElementById('thought-body')?.value.trim()||'';if(!thoughtDraft.title&&!thoughtDraft.quote&&!thoughtDraft.body&&!thoughtPending.length){notify('Add a title or thought before saving.');return}thoughtDraft.dayKey=prev?.dayKey||thoughtDraft.dayKey||localDayKey();thoughtDraft.createdAt=prev?.createdAt||thoughtDraft.createdAt||Date.now();thoughtDraft.date=prev?.date||thoughtDayLabel(thoughtDraft.dayKey,{day:'numeric',month:'short',year:'numeric'});thoughtDraft.attachments=[...(thoughtDraft.attachments||[]).filter(f=>!thoughtRemoved.includes(f.id)),...thoughtPending.map(f=>(f&&typeof f==='object'&&f.data)?f:({id:uid(),name:f.name,type:f.type||mimeFromName(f.name),data:f}))];thoughtDraft.updatedAt=Date.now();try{await persist(thoughtDraft);if(prev)notes[notes.findIndex(n=>n.id===prev.id)]=thoughtDraft;else notes.unshift(thoughtDraft);selectedId=thoughtDraft.id;thoughtDayKey=thoughtDraft.dayKey;screen='thoughts';activeTab='Text';thoughtDraft=null;thoughtPending=[];thoughtRemoved=[];render()}catch{notify('Could not save this thought. Check available device storage.')}}
function thoughtsCollection(){return notes.filter(x=>x.kind==='thought'&&!x.archived).sort((a,b)=>(b.createdAt||dateValue(b))-(a.createdAt||dateValue(a)))}
function thoughtDayKeys(){return [...new Set(thoughtsCollection().map(n=>n.dayKey||dayKeyFromDate(n.date,n.createdAt)))].sort()}
function thoughtsForDay(key){return thoughtsCollection().filter(n=>(n.dayKey||dayKeyFromDate(n.date,n.createdAt))===key)}
function setThoughtDay(direction){const days=thoughtDayKeys(),i=days.indexOf(thoughtDayKey),next=days[i+direction];if(!next)return;thoughtDayKey=next;selectedId=thoughtsForDay(next)[0]?.id||'';activeTab='Text';render()}
function thoughtNav(n){let t=thoughtsForDay(thoughtDayKey),i=t.findIndex(x=>x.id===n.id);return t.length>1?`<div class="thought-nav"><button data-action="prev-thought" aria-label="Previous thought">‹</button><span>${i+1} / ${t.length}</span><div class="thought-dots">${t.map((x,j)=>`<button class="thought-dot ${j===i?'active':''}" data-thought-index="${j}" aria-label="Go to thought ${j+1}"></button>`).join('')}</div><button data-action="next-thought" aria-label="Next thought">›</button></div>`:`<div class="thought-nav single-thought"><span>1 / 1</span></div>`}
function detailView(){
  let n=notes.find(x=>x.id===selectedId);
  if(!n)return homeView();
  if(n.kind==='thought')return thoughtView();
  const files=n.attachments||[];
  let content=n.kind==='todo'?`<ul class="detail-checklist">${(n.items||[]).map((x,i)=>`<li><button class="check ${x.done?'on':''}" data-check="${n.id}" data-index="${i}">${x.done?'✓':''}</button>${esc(x.text)}</li>`).join('')}</ul>`:n.kind==='audio'?files.length?files.map(audioMarkup).join(''):'<p>Tap edit to record or add an audio file.</p>':n.kind==='pdf'||n.kind==='files'?files.length?files.map(fileMarkup).join(''):'<p>No documents attached yet. Tap below to add a PDF or file.</p>':n.kind==='image'?files.length?`<div class="attachment-gallery">${files.filter(x=>x.type?.startsWith('image/')).map(imageMarkup).join('')}</div>`:'<p>Tap edit to add images.</p>':files.map(f=>f.type?.startsWith('image/')?imageMarkup(f):f.type?.startsWith('audio/')?audioMarkup(f):fileMarkup(f)).join('');

  let isFileKind = n.kind==='pdf'||n.kind==='files';
  let bottomAction = isFileKind ?
    `<button class="create-new" data-action="file-add"><b>+</b> Add ${n.kind==='pdf'?'PDF':'files'}</button><input id="detail-file-input" class="hidden-media-input" type="file" multiple accept="${n.kind==='pdf'?'.pdf,application/pdf':'.pdf,.doc,.docx,.txt,.rtf,.xls,.xlsx,.ppt,.pptx,application/*'}">` :
    `<button class="create-new" data-action="edit"><b>✎</b> Edit note</button>`;

  return `<section class="screen detail"><div class="detail-head"><button class="circle back" data-action="back">${backSvg()}</button><button class="circle" data-action="menu"><span class="dots">•••</span></button></div><h1 class="detail-title detail-generic">${esc(n.kind==='pdf'?'PDF':n.kind==='todo'?'To-Do':n.kind==='image'?'Images':n.kind==='audio'?'Audios':n.kind==='files'?'Files':n.title)}</h1><article class="note"><div class="note-meta"><strong>${esc(n.title)}</strong>${esc(getNoteDisplayDate(n))}</div>${!isFileKind?`<button class="edit" data-action="edit" aria-label="Edit note">${editSvg()}</button>`:''}${n.kind!=='todo'&&n.kind!=='audio'&&n.kind!=='pdf'&&n.kind!=='files'?`<p>${esc(n.body||'')}</p>`:''}${content}</article>${bottomAction}</section>`
}
function imageMarkup(f){let u=fileUrl(f),titleText=f.title||cleanPhotoTitle(f);return `<button type="button" class="attachment-image" data-view-photo="${f.id}" aria-label="Open ${esc(f.name)}"><img src="${u||''}" alt="${esc(f.name)}">${titleText?`<span>${esc(titleText)}</span>`:''}</button>`}
function audioMarkup(f){let u=fileUrl(f),bars=[13,22,17,30,20,35,15,27,39,21,32,16,25,36,19,29,14];return `<div class="audio-attachment"><div class="audio-clip-head"><span class="audio-clip-icon">♫</span><div><strong>${esc(f.name||'Audio recording')}</strong><small>${esc(f.type?.split('/')[1]?.toUpperCase()||'AUDIO')}${fileSizeText?' · '+fileSizeText:''}</small></div></div><div class="audio-mini-wave" aria-hidden="true">${bars.map((h,i)=>`<i style="--h:${h}px;--d:${i*.05}s"></i>`).join('')}</div><audio controls preload="metadata" src="${u||''}"></audio></div>`}
function fileMarkup(f){let u=fileUrl(f);return `<button type="button" class="file-attachment" data-view-file="${f.id}" style="width:100%;text-align:left"><span class="file-icon">${f.type==='application/pdf'?'PDF':'▤'}</span><span><strong>${esc(f.name)}</strong><small>${esc(f.type||'Document')} · ${formatBytes(f.data?.size||0)}</small></span><span class="download-icon" style="margin-left:auto">👁</span></button>`}
function logoSvg(){return '<svg viewBox="0 0 88 88" aria-hidden="true" fill="none" stroke="white" stroke-width="6.5" stroke-linecap="square"><path d="M44 5v78M5 44h78M16 16l56 56M72 16 16 72M30 7l28 74M7 30l74 28M58 7 30 81M81 30 7 58"/></svg>'}function plusSvg(){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 5v14M5 12h14"/></svg>'}function micSvg(){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="9" y="3" width="6" height="12" rx="3"/><path d="M5 11a7 7 0 0 0 14 0M12 18v3m-4 0h8"/></svg>'}function backSvg(){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="m15 18-6-6 6-6"/></svg>'}function editSvg(){return '<svg viewBox="0 0 24 24" width="20" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m4 16.5-.8 4.3 4.3-.8L19 8.5a2.5 2.5 0 0 0-3.5-3.5z"/><path d="m14 6 4 4"/></svg>'}function formatBytes(b){return b<1024?`${b} B`:b<1048576?`${(b/1024).toFixed(0)} KB`:`${(b/1048576).toFixed(1)} MB`}
function bindGlobal(){document.querySelectorAll('[data-filter]').forEach(x=>x.onclick=()=>{filter=x.dataset.filter;render()});document.querySelectorAll('[data-open]').forEach(x=>x.onclick=()=>openNote(x.dataset.open));document.querySelectorAll('[data-history-note]').forEach(x=>x.onclick=()=>openHistoryThought(x.dataset.historyNote));document.querySelectorAll('[data-check]').forEach(x=>x.onclick=e=>{e.stopPropagation();toggleCheck(x.dataset.check,+x.dataset.index)});document.querySelectorAll('[data-tab]').forEach(x=>x.onclick=()=>{activeTab=x.dataset.tab;render()});document.querySelectorAll('[data-action]').forEach(x=>x.onclick=e=>{e.stopPropagation();handleAction(x.dataset.action,x)});document.querySelectorAll('[data-thought-index]').forEach(x=>x.onclick=()=>selectThoughtAt(+x.dataset.thoughtIndex));document.querySelectorAll('[data-view-photo]').forEach(b=>b.onclick=()=>{let photoId=b.dataset.viewPhoto;for(const n of notes){let p=(n.attachments||[]).find(x=>x.id===photoId);if(p){openPhotoViewer(n,p);break}}});document.querySelectorAll('[data-view-file]').forEach(b=>b.onclick=()=>{let fileId=b.dataset.viewFile;for(const n of notes){let f=(n.attachments||[]).find(x=>x.id===fileId);if(f){openFileViewer(f);break}}});const detailFileInput=document.getElementById('detail-file-input');if(detailFileInput){detailFileInput.onchange=async()=>{const rawFiles=Array.from(detailFileInput.files||[]);detailFileInput.value='';if(!rawFiles.length)return;notify('Adding file…');const processed=await processMultipleFiles(rawFiles);const n=notes.find(x=>x.id===selectedId);if(n){n.attachments=[...(n.attachments||[]),...processed];n.updatedAt=Date.now();await persist(n);render();notify(`${processed.length} file(s) added.`)}}};const deck=document.querySelector('[data-thought-deck]');if(deck){const currentCard=deck.querySelector('.thought-current');let startX=0,startY=0,isDragging=false;deck.onpointerdown=e=>{startX=e.clientX;startY=e.clientY;isDragging=true;if(currentCard)currentCard.style.transition='none'};deck.onpointermove=e=>{if(!isDragging||!currentCard)return;let dx=e.clientX-startX,dy=e.clientY-startY,rot=dx*0.06;currentCard.style.transform=`translate(${dx}px, ${dy}px) rotate(${rot}deg)`};const endDrag=e=>{if(!isDragging)return;isDragging=false;let dx=e?e.clientX-startX:0,dy=e?e.clientY-startY:0,dist=Math.hypot(dx,dy);if(dist>45&&currentCard){let rot=dx*0.08;currentCard.style.transition='transform .28s cubic-bezier(.2,.8,.2,1), opacity .28s';currentCard.style.transform=`translate(${dx*3.5}px, ${dy*3.5}px) rotate(${rot*2}deg)`;currentCard.style.opacity='0';setTimeout(()=>{cycleThought(dx<0||dy<-35?1:-1)},200)}else if(currentCard){currentCard.style.transition='transform .3s cubic-bezier(.2,.8,.2,1)';currentCard.style.transform=''}};deck.onpointerup=endDrag;deck.onpointercancel=endDrag;deck.onkeydown=e=>{if(e.key==='ArrowLeft'){e.preventDefault();cycleThought(-1)}if(e.key==='ArrowRight'){e.preventDefault();cycleThought(1)}}}const t=document.getElementById('thought-title'),q=document.getElementById('thought-quote'),b=document.getElementById('thought-body');if(t)t.oninput=()=>thoughtDraft.title=t.value;if(q)q.oninput=()=>thoughtDraft.quote=q.value;if(b)b.oninput=()=>thoughtDraft.body=b.value;for(const id of ['thought-camera-input','thought-image-input','thought-audio-input']){const input=document.getElementById(id);if(input)input.onchange=async()=>{const rawFiles=Array.from(input.files||[]);if(!rawFiles.length)return;notify('Processing file…');const processed=await processMultipleFiles(rawFiles);thoughtPending.push(...processed);render()}}document.querySelectorAll('[data-remove-thought-file]').forEach(x=>x.onclick=e=>{e.stopPropagation();let id=x.dataset.removeThoughtFile;if(thoughtPending.some(f=>f.name===id))thoughtPending=thoughtPending.filter(f=>f.name!==id);else thoughtRemoved.push(id);render()})}
function openHistoryThought(id){const n=notes.find(x=>x.id===id&&x.kind==='thought');if(!n)return;selectedId=id;thoughtDayKey=n.dayKey||dayKeyFromDate(n.date,n.createdAt);screen='thoughts';activeTab='Text';transitionRender()}
function openNote(id){selectedId=id;let n=notes.find(x=>x.id===id);if(id==='thought'||n?.kind==='thought'){screen='thoughts';thoughtDayKey=n?.dayKey||localDayKey()}else if(id==='highlights'||id==='snapshots'||(n?.kind==='image'&&['highlights','snapshots'].includes(n.id))){screen='album'}else if(id==='audio'||n?.kind==='audio'){screen='audio'}else{screen='detail'}activeTab='Text';transitionRender()}
async function toggleCheck(id,index){let n=notes.find(x=>x.id===id);if(n?.items?.[index]){n.items[index].done=!n.items[index].done;n.updatedAt=Date.now();await persist(n);render()}}
function transitionRender(){app.classList.add('leaving');setTimeout(()=>{app.classList.remove('leaving');render()},140)}
function handleAction(action,el){if(action==='back'){if(screen==='thoughtEdit'){thoughtDraft=null;thoughtPending=[];thoughtRemoved=[];screen=editorId?'thoughts':thoughtEditReturn==='thoughtHistory'?'thoughtHistory':'home'}else if(screen==='thoughtHistory')screen='thoughts';else screen='home';transitionRender()}else if(action==='create')createChooser();else if(action==='new-thought')beginThoughtEdit(null);else if(action==='edit'){let n=notes.find(x=>x.id===selectedId);if(n?.kind==='thought')beginThoughtEdit(n);else if(n?.kind==='audio')openAudioEditor(n);else openEditor(n)}else if(action==='thought-history'){screen='thoughtHistory';render()}else if(action==='thought-today'){thoughtDayKey=localDayKey();selectedId=thoughtsForDay(thoughtDayKey)[0]?.id||'';screen='thoughts';render()}else if(action==='day-prev')setThoughtDay(-1);else if(action==='day-next')setThoughtDay(1);else if(action==='menu')showMenu();else if(action==='record')toggleRecord();else if(action==='morning'){screen='morning';transitionRender()}else if(action==='morning-thought'){let n=thoughtsForDay(localDayKey())[0]||latest('thought');if(n)openNote(n.id);else{thoughtDayKey=localDayKey();screen='thoughts';render()}}else if(action==='thought-ideas')showThoughtIdeas();else if(action==='thought-camera')triggerFileInput('thought-camera-input');else if(action==='thought-images')triggerFileInput('thought-image-input');else if(action==='thought-audio')triggerFileInput('thought-audio-input')||triggerFileInput('thought-view-audio');else if(action==='thought-options')showThoughtMenu();else if(action==='save-thought')saveThoughtEdit();else if(action==='focus-thought'){const field=document.getElementById('thought-body');field?.focus();field?.setSelectionRange(field.value.length,field.value.length)}else if(action==='daily-notes')showDailySummary();else if(action==='album-add')triggerFileInput('album-files');else if(action==='audio-add')triggerFileInput('audio-library-files');else if(action==='file-add')triggerFileInput('detail-file-input');else if(action==='prev-thought'||action==='next-thought')cycleThought(action==='next-thought'?1:-1);}
function selectThoughtAt(index){const a=thoughtsForDay(thoughtDayKey),i=a.findIndex(n=>n.id===selectedId);if(index<0||index>=a.length||index===i)return;thoughtSlide=index>i?'slide-next':'slide-prev';selectedId=a[index].id;render()}
function cycleThought(d){const a=thoughtsForDay(thoughtDayKey);if(a.length<2)return;let i=a.findIndex(n=>n.id===selectedId);thoughtSlide=d>0?'slide-next':'slide-prev';selectedId=a[(i+d+a.length)%a.length]?.id||selectedId;render()}
function modalShell(content){overlay.innerHTML=`<div class="modal-back"><div class="modal">${content}</div></div>`;overlay.querySelector('.modal-back').onclick=e=>{if(e.target.classList.contains('modal-back'))closeModal()}}
function closeModal(){overlay.innerHTML='';pendingFiles=[];removedFiles=[]}
  function createChooser(){modalShell(`<h2>Create something</h2><div class="menu-items create-options">${[['thought','Thought of the day'],['text','Text note'],['todo','To-Do list'],['image','Add images'],['audio','Audio note'],['files','Add files'],['pdf','Add PDF']].map(([k,t])=>`<button data-kind="${k}">${t}</button>`).join('')}</div><div class="modal-actions"><button class="action" data-close>Cancel</button></div>`);overlay.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>b.dataset.kind==='thought'?beginThoughtEdit(null):b.dataset.kind==='audio'?(closeModal(),document.getElementById('audio-library-files')?.click()):openEditor(null,b.dataset.kind));overlay.querySelector('[data-close]').onclick=closeModal}
function kindLabel(k){return({todo:'To-Do list',image:'image note',audio:'audio note',files:'file note',pdf:'PDF note',thought:'thought of the day',text:'text note'})[k]||'note'}
async function saveEditor(){let title=overlay.querySelector('#e-title').value.trim()||'Untitled note',body=overlay.querySelector('#e-body').value.trim(),quote=overlay.querySelector('#e-quote')?.value.trim()||'',existing=notes.find(x=>x.id===editorId),previous=existing?structuredClone(existing):null,kind=existing?.kind||(selectedCreateKind||'text');if(existing)kind=existing.kind;let attachments=[...(existing?.attachments||[]).filter(f=>!removedFiles.includes(f.id)),...pendingFiles.map(f=>(f&&typeof f==='object'&&f.data)?f:({id:uid(),name:f.name,type:f.type||mimeFromName(f.name),data:f}))];let n=existing||{id:uid(),kind,date:new Date().toLocaleString(),createdAt:Date.now()};n.title=title;n.body=body;n.updatedAt=Date.now();if(kind==='thought')n.quote=quote;if(kind==='todo')n.items=body.split(/\n+/).map(t=>t.trim()).filter(Boolean).map((text,i)=>({text,done:existing?.items?.[i]?.done||false}));n.attachments=attachments;if(kind==='image'&&!attachments.length){notify('Choose at least one image before saving.');return}if(kind==='audio'&&!attachments.some(f=>f.type?.startsWith('audio/'))){notify('Add an audio file, or record one with the microphone button.');return}if(kind==='pdf'&&!attachments.some(f=>f.type==='application/pdf'||f.name.toLowerCase().endsWith('.pdf'))){notify('Choose a PDF file before saving.');return}if(kind==='files'&&!attachments.length){notify('Choose at least one file before saving.');return}if(!existing)notes.unshift(n);try{await persist(n);selectedId=n.id;screen=kind==='thought'?'thoughts':kind==='audio'?'audio':'detail';activeTab='Text';closeModal();render()}catch{if(existing)Object.assign(existing,previous);else notes=notes.filter(x=>x.id!==n.id);notify('Could not save. The attachment may be too large for this device.')}}
function mimeFromName(name){let ext=name.toLowerCase().split('.').pop();return({pdf:'application/pdf',jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',webp:'image/webp',gif:'image/gif',mp3:'audio/mpeg',m4a:'audio/mp4',wav:'audio/wav',webm:'audio/webm'})[ext]||'application/octet-stream'}
let selectedCreateKind='text';
function openEditor(n,kind){editorId=n?.id||null;selectedCreateKind=kind||n?.kind||'text';pendingFiles=[];removedFiles=[];let k=selectedCreateKind,thought=k==='thought',itemsText=k==='todo'?(n?.items||[]).map(x=>x.text).join('\n'):'';let title=thought?'':(n?.title||'');const uploadField=k==='todo'?'':`<label class="upload-label">${thought?'Add images or audio':k==='image'?'Add images':k==='pdf'?'Choose PDF files':k==='files'?'Choose files':k==='audio'?'Choose audio files':'Add attachments'}<input id="e-files" class="file-input" type="file" multiple accept="${thought?'image/*,audio/*':k==='image'?'image/*':k==='pdf'?'.pdf,application/pdf':k==='audio'?'audio/*':k==='files'?'.pdf,.doc,.docx,.txt,.rtf,.xls,.xlsx,.ppt,.pptx,application/*':'image/*,audio/*,application/pdf,.pdf'}"></label><div class="pending-files" id="pending-files">${(n?.attachments||[]).map(f=>`<span>${esc(f.name)} <button type="button" data-remove-file="${esc(f.id)}" aria-label="Remove ${esc(f.name)}">×</button></span>`).join('')}</div>`;modalShell(`<h2>${n?(k==='todo'?'Edit To-Do list':'Edit note'):thought?'New thought of the day':'New '+kindLabel(k)}</h2><label>Title<input class="field" id="e-title" value="${esc(title)}" placeholder="Title"></label>${thought?'<label>Thought<textarea class="field" id="e-quote" rows="2" placeholder="A line to remember">'+esc(n?.quote||'')+'</textarea></label>':''}<label>${k==='todo'?'Checklist · one item per line':'Content'}<textarea class="field" id="e-body" rows="4" placeholder="${k==='todo'?'Vegetables\nFruit\nCoffee':'Write something worth remembering'}">${esc(thought?n?.body||'':k==='todo'?itemsText:n?.body||'')}</textarea></label>${uploadField}${n?`<div class="menu-items note-actions"><button data-note-action="favorite">${n.favorite?'★ Remove favorite':'☆ Favorite'}</button><button data-note-action="pin">${n.pinned?'Unpin':'Pin'}</button><button data-note-action="duplicate">Duplicate</button><button data-note-action="archive">Archive</button><button data-note-action="share">Share</button></div>`:''}<div class="modal-actions">${n?'<button class="action danger" data-delete>Delete</button>':''}<button class="action" data-close>Cancel</button><button class="action primary" data-save>Save</button></div>`);
overlay.querySelector('[data-close]').onclick=closeModal;overlay.querySelector('[data-save]').onclick=saveEditor;overlay.querySelector('[data-delete]')?.addEventListener('click',deleteCurrent);let input=overlay.querySelector('#e-files');if(input)input.onchange=async()=>{const rawFiles=Array.from(input.files||[]);if(!rawFiles.length)return;notify('Processing file…');const processed=await processMultipleFiles(rawFiles);pendingFiles=[...pendingFiles,...processed];overlay.querySelector('#pending-files').insertAdjacentHTML('beforeend',processed.map(f=>`<span>＋ ${esc(f.name)}</span>`).join(''))};overlay.querySelectorAll('[data-remove-file]').forEach(b=>b.onclick=()=>{removedFiles.push(b.dataset.removeFile);b.parentElement.remove()});overlay.querySelectorAll('[data-note-action]').forEach(b=>b.onclick=()=>noteAction(b.dataset.noteAction))}
async function deleteCurrent(){if(!confirm('Delete this note permanently?'))return;let n=notes.find(x=>x.id===editorId);if(n){notes=notes.filter(x=>x.id!==editorId);await removePersist(editorId)}closeModal();screen='home';render()}
async function noteAction(a){let n=notes.find(x=>x.id===editorId);if(!n)return;if(a==='favorite')n.favorite=!n.favorite;if(a==='pin')n.pinned=!n.pinned;if(a==='archive'){n.archived=true;await persist(n);closeModal();screen='home';render();return}if(a==='duplicate'){let copy=structuredClone(n);copy.id=uid();copy.title+=' copy';copy.pinned=false;copy.createdAt=Date.now();notes.unshift(copy);await persist(copy);notify('Note duplicated');closeModal();render();return}if(a==='share'){let txt=`${n.title}\n${n.quote||''}\n${n.body||''}`;if(navigator.share)navigator.share({title:n.title,text:txt});else if(navigator.clipboard)navigator.clipboard.writeText(txt).then(()=>notify('Note copied'));return}await persist(n);openEditor(n)}
async function toggleRecord(){if(recording?.state==='recording'){recording.stop();recording=null;render();return}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){notify('Microphone recording is not supported in this browser.');return}try{let stream=await navigator.mediaDevices.getUserMedia({audio:true}),chunks=[],r=new MediaRecorder(stream);recording=r;notify('Recording… tap the microphone again to finish.');r.ondataavailable=e=>e.data.size&&chunks.push(e.data);r.onstop=async()=>{stream.getTracks().forEach(t=>t.stop());recording=null;let blob=new Blob(chunks,{type:r.mimeType||'audio/webm'}),note={id:uid(),kind:'audio',title:`Voice note ${new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}`,body:'',date:new Date().toLocaleString(),createdAt:Date.now(),updatedAt:Date.now(),attachments:[{id:uid(),name:'Voice recording',type:blob.type,data:blob}]};notes.unshift(note);try{await persist(note);notify('Voice note saved.');render()}catch{notes.shift();notify('Recording is too large to save.')}};r.start();render()}catch{recording=null;notify('Microphone access was not granted.');render()}}
function showMenu(){modalShell(`<h2>Your Notes</h2><div class="menu-items"><button data-menu="morning">☼　Daily overview</button><button data-menu="search">⌕　Search notes</button><button data-menu="sort">↕　Sort notes</button><button data-menu="favorites">☆　Favorites</button><button data-menu="archive">▱　Archive</button><button data-menu="share">↗　Share all notes</button></div><div class="modal-actions"><button class="action" data-close>Done</button></div>`);overlay.querySelector('[data-close]').onclick=closeModal;overlay.querySelectorAll('[data-menu]').forEach(b=>b.onclick=()=>{let a=b.dataset.menu;if(a==='morning'){closeModal();screen='morning';render()}if(a==='search')searchDialog();if(a==='sort')sortDialog();if(a==='favorites'){filter='Important';closeModal();screen='home';render()}if(a==='archive')archiveDialog();if(a==='share'&&navigator.share)navigator.share({title:'Your Notes',text:notes.map(n=>`${n.title}: ${n.body||''}`).join('\n')})})}
function showThoughtIdeas(){const ideas=['Find joy in the small things.','One step at a time is still progress.','Let today be softer than yesterday.','I am allowed to begin again.','Notice what is already going right.'];modalShell(`<h2>A thought to begin with</h2><div class="menu-items">${ideas.map(v=>`<button data-idea="${esc(v)}">${esc(v)}</button>`).join('')}</div><div class="modal-actions"><button class="action" data-close>Close</button></div>`);overlay.querySelector('[data-close]').onclick=closeModal;overlay.querySelectorAll('[data-idea]').forEach(b=>b.onclick=()=>{thoughtDraft.quote=b.dataset.idea;closeModal();render()})}
function showThoughtMenu(){let existing=notes.find(n=>n.id===editorId);modalShell(`<h2>Thought tools</h2><div class="menu-items"><button data-thought-tool="audio">♫　Attach an audio note</button>${existing?'<button data-thought-tool="more">•••　More thought options</button>':''}</div><div class="modal-actions"><button class="action" data-close>Done</button></div>`);overlay.querySelector('[data-close]').onclick=closeModal;overlay.querySelector('[data-thought-tool="audio"]').onclick=()=>{closeModal();document.getElementById('thought-audio-input')?.click()};overlay.querySelector('[data-thought-tool="more"]')?.addEventListener('click',()=>{closeModal();openEditor(existing)})}
function showDailySummary(){let todo=notes.filter(n=>n.kind==='todo'&&!n.archived).flatMap(n=>n.items||[]),done=todo.filter(x=>x.done).length,thoughtCount=notes.filter(n=>n.kind==='thought'&&!n.archived).length,photoCount=notes.filter(n=>n.kind==='image'&&!n.archived).length;modalShell(`<h2>Your day, at a glance</h2><div class="summary-stats"><div><strong>${done}/${todo.length}</strong><span>checklist items done</span></div><div><strong>${thoughtCount}</strong><span>thoughts saved</span></div><div><strong>${photoCount}</strong><span>photo notes</span></div></div><div class="modal-actions"><button class="action" data-close>Close</button><button class="action primary" data-go-home>All notes</button></div>`);overlay.querySelector('[data-close]').onclick=closeModal;overlay.querySelector('[data-go-home]').onclick=()=>{closeModal();screen='home';render()}}
function searchDialog(){modalShell(`<h2>Search notes</h2><input id="search-field" class="field" value="${esc(query)}" placeholder="Search titles and content"><div class="modal-actions"><button class="action" data-close>Cancel</button><button class="action primary" data-search>Search</button></div>`);overlay.querySelector('[data-close]').onclick=closeModal;overlay.querySelector('[data-search]').onclick=()=>{query=overlay.querySelector('#search-field').value;closeModal();screen='home';render()};overlay.querySelector('#search-field').focus()}
function sortDialog(){modalShell(`<h2>Sort notes</h2><div class="menu-items">${[['edited','Recently edited'],['oldest','Oldest first'],['alpha','Alphabetical']].map(([v,t])=>`<button data-sort="${v}">${sort===v?'●':'○'}　${t}</button>`).join('')}</div>`);overlay.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{sort=b.dataset.sort;closeModal();render()})}
function archiveDialog(){let a=notes.filter(n=>n.archived);modalShell(`<h2>Archived notes</h2>${a.length?a.map(n=>`<p>${esc(n.title)} <button class="action" data-restore="${n.id}">Restore</button></p>`).join(''):'<p>No archived notes.</p>'}<div class="modal-actions"><button class="action" data-close>Done</button></div>`);overlay.querySelector('[data-close]').onclick=closeModal;overlay.querySelectorAll('[data-restore]').forEach(b=>b.onclick=async()=>{let n=notes.find(x=>x.id===b.dataset.restore);n.archived=false;await persist(n);archiveDialog()})}
function notify(t){let old=document.querySelector('.toast');old?.remove();let el=document.createElement('div');el.className='toast';el.textContent=t;document.body.append(el);setTimeout(()=>el.remove(),2600)}

window.handleAndroidBack=function(){
  console.log('[AndroidBack] Invoked. Overlay active:', !!overlay?.firstElementChild, 'Current screen:', screen);
  if(overlay&&overlay.firstElementChild){
    closeModal();
    return true;
  }
  if(screen==='thoughtEdit'){
    thoughtDraft=null;
    thoughtPending=[];
    thoughtRemoved=[];
    screen=editorId?'thoughts':(thoughtEditReturn==='thoughtHistory'?'thoughtHistory':'home');
    transitionRender();
    return true;
  }
  if(screen==='thoughtHistory'){
    screen='thoughts';
    transitionRender();
    return true;
  }
  if(screen!=='home'){
    screen='home';
    transitionRender();
    return true;
  }
  return false;
};

init();
